static T Erstes<T>(T[] werte)
{
    return werte[0];
}

int[] zahlen = { 7, 3, 9 };
string[] namen = { "Lena", "Ali" };

Console.WriteLine(Erstes(zahlen));
Console.WriteLine(Erstes<string>(namen));
// Ausgabe:
// 7
// Lena

var b1 = new Box<int>(42);
var b2 = new Box<string>("Schlüssel");
Console.WriteLine(b1.Inhalt + 1);
Console.WriteLine(b2.Inhalt.Length);
// Ausgabe:
// 43
// 9

class Box<T>
{
    public T Inhalt { get; set; }

    public Box(T inhalt)
    {
        Inhalt = inhalt;
    }
}

static T Groesser<T>(T a, T b)
{
    return a > b ? a : b;   // Fehler CS0019: > ist für T nicht definiert
}

static T Groesser<T>(T a, T b) where T : IComparable<T>
{
    return a.CompareTo(b) > 0 ? a : b;
}

Console.WriteLine(Groesser(4, 11));
Console.WriteLine(Groesser("Apfel", "Birne"));
// Ausgabe:
// 11
// Birne

